INSERT INTO `wiki_articles` (`category_id`, `title`, `slug`, `summary`, `body`, `author_id`, `display_order`, `is_published`, `views`, `created_at`, `updated_at`) VALUES
  (1, 'Как начать играть', 'kak-nachat-igrat', 'Установка игры, клиента и первое подключение к серверу', '[b]Шаг 1. Игра.[/b] Нужна лицензионная GTA San Andreas версии 1.0 (US). Если у вас другая версия, установите даунгрейдер до 1.0.\n\n[b]Шаг 2. Клиент.[/b] Установите клиент SA-MP 0.3.7 или лаунчер open.mp. Ссылки есть на странице [url=/start.php]Начать игру[/url].\n\n[b]Шаг 3. Ник.[/b] На сервере принят формат [b]Имя_Фамилия[/b], например [icode]John_Smith[/icode]. Ник указывается в клиенте перед подключением.\n\n[b]Шаг 4. Подключение.[/b] Добавьте сервер в избранное по адресу, который указан на главной странице, и нажмите «Подключиться».\n\n[b]Шаг 5. Регистрация.[/b] Придумайте надёжный пароль и не сообщайте его никому. Администрация никогда не спрашивает пароли.\n\n[spoiler=Если игра не запускается]\n[list]\n[*]Запустите игру от имени администратора.\n[*]Отключите сторонние моды и CLEO-скрипты.\n[*]Проверьте, что антивирус не удалил файлы клиента.\n[*]Если не помогло - создайте тему в разделе «Техническая поддержка».\n[/list]\n[/spoiler]', NULL, 1, 1, 0, '2026-10-06 00:00:00', '2026-10-06 00:00:00'),
  (1, 'Правильный RP ник', 'pravilnyy-rp-nik', 'Каким должен быть ник персонажа', 'Ник - это имя вашего персонажа. На RP сервере он должен быть похож на настоящее имя человека.\n\n[b]Правильно:[/b] [icode]Michael_Brown[/icode], [icode]Ivan_Petrov[/icode]\n[b]Неправильно:[/b] [icode]Killer_2007[/icode], [icode]Pro_Gamer[/icode], [icode]Vasya[/icode]\n\n[list]\n[*]Имя и фамилия пишутся латиницей через нижнее подчёркивание.\n[*]Нельзя использовать имена известных людей и оскорбительные слова.\n[*]Цифры и лишние символы в нике не допускаются.\n[/list]', NULL, 2, 1, 0, '2026-10-06 00:00:00', '2026-10-06 00:00:00'),
  (1, 'Основные RP термины', 'osnovnye-rp-terminy', 'IC, OOC, MG, DM, PG и другие понятия', '[b]RP (Role Play)[/b] - игра по ролям: вы ведёте себя как житель города, а не как игрок.\n\n[b]IC (In Character)[/b] - всё, что происходит в игре с вашим персонажем.\n[b]OOC (Out Of Character)[/b] - всё, что не относится к игре. Для OOC-общения используется чат [icode]/b[/icode] или аналог на сервере.\n\n[b]MG (MetaGaming)[/b] - использование в игре информации, которую персонаж знать не может (из Discord, стрима, ника над головой).\n[b]DM (DeathMatch)[/b] - убийство или нападение без RP-причины.\n[b]DB (DriveBy)[/b] - убийство или нанесение урона с транспорта без причины.\n[b]PG (PowerGaming)[/b] - нереалистичные действия: бежать с тяжёлым ранением, драться одному против пятерых без страха.\n[b]TK (TeamKill)[/b] - убийство своих (членов своей организации).\n[b]SK (SpawnKill)[/b] - убийство на месте появления.\n[b]RK (RevengeKill)[/b] - месть за свою смерть после возрождения.\n\nТочные правила и наказания смотрите в разделе «Правила проекта» на форуме.', NULL, 3, 1, 0, '2026-10-06 00:00:00', '2026-10-06 00:00:00');
